CREATE TABLE IF NOT EXISTS corporate_resolutions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), resolution_title text NOT NULL, resolution_type text NOT NULL, decision_summary text NOT NULL, authority_basis text, approval_status text NOT NULL DEFAULT 'Draft', resolution_date date, effective_date date, implementation_owner text, reference_number text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());